// Generated by vibelang from src/state/usageProgress.ts; the migrate flow writes it again with each batch.
export function usageEnvironmentProgress(environment, refreshing = false) {
    const { summary } = environment;
    if (!environment.isConnected || environment.error !== null)
        return { phase: "inactive" };
    if (summary === null)
        return { phase: "loading" };
    if (refreshing)
        return { phase: "stale" };
    if (!environment.isPending)
        return { phase: "ready" };
    const providers = [
        ...new Set(summary.sources.flatMap((source) => (source.refreshing ? [source.fingerprint.provider] : []))),
    ];
    return providers.length > 0
        ? { phase: "partway", providers }
        : { phase: "stale" };
}
export function updatingProvidersLabel(providers, providerLabel) {
    return providers.length === 1
        ? `Updating ${providerLabel(providers[0])}…`
        : `Updating ${providers.length} providers…`;
}
export function usageProgress(environments, { refreshing = false, providerLabel, }) {
    const progress = environments.map((environment) => ({
        label: environment.label,
        ...usageEnvironmentProgress(environment, refreshing),
    }));
    const waiting = progress.filter(({ phase }) => phase === "loading" || phase === "stale");
    const providers = [
        ...new Set(progress.flatMap((entry) => (entry.phase === "partway" ? entry.providers : []))),
    ];
    const answered = progress.some(({ phase }) => phase === "partway" || phase === "ready");
    return {
        dimmed: !answered && progress.some(({ phase }) => phase === "stale"),
        label: waiting.length === 0
            ? providers.length === 0
                ? null
                : updatingProvidersLabel(providers, providerLabel)
            : environments.length === 1
                ? "Updating…"
                : waiting.length === 1
                    ? `Updating ${waiting[0].label}…`
                    : `Updating ${waiting.length} environments…`,
    };
}
export function usageLoadingState(environments, refreshing = false) {
    const providers = new Set();
    let everyProvider = false;
    for (const environment of environments) {
        const progress = usageEnvironmentProgress(environment, refreshing);
        if (progress.phase === "loading" || progress.phase === "stale")
            everyProvider = true;
        if (progress.phase === "partway")
            for (const provider of progress.providers)
                providers.add(provider);
    }
    return { partial: everyProvider || providers.size > 0, everyProvider, providers };
}
